// Sends report emails to shop owners.
import { loadReport, saveReport } from './store.js';
import { sendMail } from './mail.js';
import { renderCorrection, renderDaily, renderWeekly } from './report_render.js';

// Saves the render, then mails the copy read back from the store (ADR 0024).
async function sendReport(shop, kind, key, html, subject) {
  await saveReport(key, html);
  const body = await loadReport(key);
  await sendMail(shop.email, subject, body);
  return { shopId: shop.id, kind, bytes: html.length };
}

export async function sendDailyReport(shop, rows, day) {
  const html = renderDaily(shop, rows, day);
  return sendReport(shop, 'daily', `daily-${shop.id}-${day}`, html, `Your report for ${day}`);
}

export async function sendWeeklyReport(shop, rows, weekStart) {
  const html = renderWeekly(shop, rows, weekStart);
  return sendReport(shop, 'weekly', `weekly-${shop.id}-${weekStart}`, html, `Your report for the week of ${weekStart}`);
}

export async function sendCorrection(shop, rows, day, note) {
  const html = renderCorrection(shop, rows, day, note);
  return sendReport(shop, 'correction', `correction-${shop.id}-${day}`, html, `Corrected report for ${day}`);
}
